			setPayload(runtime.payload);
			setStatus("idle");
			return true;
		} catch {
			if (
				mounted.current &&
				!current.signal.aborted &&
				generation.current === id
			)
				setStatus("error");
			return false;
		}
	};
	return { payload, status, change, cancel };
}

